/**
 * argparse-state-machine.mjs — exhaustive differential campaign against the
 * argparse port of test7.py.
 *
 * Usage:  node argparse-state-machine.mjs [shardIndex shardCount]
 *
 * Every case is a full argv vector handed to BOTH the reference PyInstaller
 * binary and the Node port with byte-identical bytes; stdout, stderr and exit
 * code are all compared.
 */
import { runSuite, checkCase } from '/tmp/dh/harness.mjs';

const argvIn = process.argv.slice(2);
const SHARD = argvIn.length >= 2 ? parseInt(argvIn[0], 10) : 0;
const SHARDS = argvIn.length >= 2 ? parseInt(argvIn[1], 10) : 1;

// ---------------------------------------------------------------- case builder
const cases = [];
const seen = new Set();
function add(argv, tag) {
  const key = JSON.stringify([tag, argv.map(String)]);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push({ argv, label: `${tag}: ` + argv.map((a) => JSON.stringify(String(a))).join(' ') });
}

// deterministic PRNG so reruns are reproducible
let _s = 0x2f6e2b1;
const rnd = () => ((_s = (_s * 1103515245 + 12345) & 0x7fffffff) / 0x80000000);
const pick = (arr) => arr[Math.floor(rnd() * arr.length) % arr.length];

// -------------------------------------------------------- 1. exhaustive tuples
// Every ordered tuple of length 0..3 over a 20-token alphabet that covers the
// whole state machine: known options, '=' forms, abbreviations, unknown
// options, the '--' separator, plain values, negative-number-ish values,
// values with spaces, the empty string.
const ALPHA3 = [
  '--a', '--b', '-h', '--', '--a=1', '--b=2', '--a=', '--h', '--ab', '-x',
  '-', '1', '', '-5', '-1.', ' x', '--a=-x', '-hx', '--help', '--5',
];
add([], 'len0');
for (const t of ALPHA3) add([t], 'len1');
for (const a of ALPHA3) for (const b of ALPHA3) add([a, b], 'len2');
for (const a of ALPHA3) for (const b of ALPHA3) for (const c of ALPHA3) add([a, b, c], 'len3');

// length 4 over a smaller alphabet, still exhaustive
const ALPHA4 = ['--a', '--b', '-h', '--', '1', '-x', '--a=1', ''];
for (const a of ALPHA4)
  for (const b of ALPHA4)
    for (const c of ALPHA4)
      for (const d of ALPHA4) add([a, b, c, d], 'len4');

// ------------------------------------------------- 2. counts 5..8, randomised
const ALPHA_BIG = [
  '--a', '--b', '-h', '--help', '--h', '--he', '--', '--a=1', '--b=2', '--a=',
  '--a==1', '--a=-x', '-x', '-a', '---a', '--A', '-hx', '-h=x', '--help=x',
  '-', '', '1', '2', 'x', '-5', '-0009', '-.5', '-0.0', '-1.', '-1.5e3', '-5x',
  '- 5', '-5 ', '+5', '--5', ' ', ' lead', '--ab', '--aa', '--b=', '=1', 'a=b',
];
for (let n = 5; n <= 8; n += 1) {
  for (let i = 0; i < 900; i += 1) {
    const argv = [];
    for (let k = 0; k < n; k += 1) argv.push(pick(ALPHA_BIG));
    add(argv, `len${n}`);
  }
}

// -------------------------------------------- 3. negative numbers / value-ish
const VALUES = [
  '-5', '-0009', '-.5', '-0.0', '-0', '-00', '-.0', '-1.', '-1.5e3', '-5x',
  '- 5', '-5 ', ' -5', '+5', '--5', '-', '--', '-.', '-..5', '-5.5', '-5.',
  '-12345678901234567890', '-0.000', '-1e5', '-1_0', '-\t5', '-5\t', '-x',
  '-hx', '-h', '--a', '--b', '--help', '--h', '--ab', '---5', '-=5', '-5=',
  '-5-5', '-¹5', '-۵', '-٥', '-٥٦', '-٥.٥',
  '-５', '-०', '-๕', '-⁵', '-½', '-٥x',
  '-٥ ', '- ٥', '−5', '-5٥',
];
for (const v of VALUES) {
  add(['--a', v, '--b', '2'], 'neg');
  add(['--b', '2', '--a', v], 'neg');
  add(['--a', '1', '--b', v], 'neg');
  add(['--a=' + v, '--b', '2'], 'neg');
  add(['--a', v], 'neg');
  add([v], 'neg');
  add([v, '--a', '1', '--b', '2'], 'neg');
  add(['--a', '1', '--b', '2', v], 'neg');
  add(['--a', v, '--b', v], 'neg');
}

// ------------------------------------------------------- 4. abbreviation space
const ABBR = [];
for (const base of ['--help', '--a', '--b', '-h']) {
  for (let i = 1; i <= base.length; i += 1) ABBR.push(base.slice(0, i));
}
for (const extra of ['x', 'X', '=', '=x', '==x', '-', '--', 'a', 'b', 'h', 'e', 'lp', 'p', ' ']) {
  for (const base of ['--h', '--he', '--hel', '--help', '--a', '--b', '-h', '--', '-']) {
    ABBR.push(base + extra);
  }
}
ABBR.push('--HELP', '--A', '--B', '-H', '--aa', '--ab', '--ba', '--bb', '--hh',
  '--helpp', '--helo', '---a', '----', '-a', '-b', '-e', '-l', '-p', '-ha',
  '-hb', '-hh', '-hhh', '-h-x', '-h=', '-h==', '-=', '-=x', '--=', '--=x',
  '--=1', '=--a', '--a-', '--a-b', '--_a', '--a_', '-h ', ' -h', '--a ', ' --a');
for (const t of ABBR) {
  add([t], 'abbr');
  add([t, '1'], 'abbr');
  add(['--a', '1', '--b', '2', t], 'abbr');
  add([t, '--a', '1', '--b', '2'], 'abbr');
  add(['--a', '1', t, '--b', '2'], 'abbr');
  add([t, t], 'abbr');
}

// ------------------------------------------------------------ 5. '=' forms
const EQ = [
  '--a=1', '--a=', '--a==', '--a==1', '--a=-x', '--a=-5', '--a=--', '--a=--b',
  '--a= ', '--a=  x', '--a=1=2', '--a==-x', '--a=\t', '--a==', '--b=1',
  '--b=', '--b=-x', '--b==2', '--h=1', '--he=1', '--help=', '--help=1',
  '--help==', '-h=1', '-h=', '--=1', '--A=1', '--ab=1', '--aa=1', '-x=1',
  '-a=1', '---a=1', '--a=--b=2', '=1', 'a=1', '--=', '--a=٥',
];
for (const t of EQ) {
  add([t], 'eq');
  add([t, '--b', '2'], 'eq');
  add(['--a', '1', t], 'eq');
  add([t, '--a', '9', '--b', '8'], 'eq');
  add([t, t], 'eq');
  add(['--b=2', t], 'eq');
}

// ------------------------------------------------------ 6. repeated options
const REP = [
  ['--a', '1', '--a', '2', '--b', '3'],
  ['--a', '1', '--b', '2', '--a', '3'],
  ['--a=1', '--a=2', '--b=3'],
  ['--a', '1', '--a=2', '--b', '3'],
  ['--b', '1', '--b', '2', '--a', '3'],
  ['--a', '1', '--b', '2', '--b', '3', '--a', '4'],
  ['--h', '--a', '1', '--b', '2', '--h'],
  ['--a', '1', '--a', '--b', '2'],
  ['--a', '--a', '--b', '2'],
  ['--a', '1', '--b', '2', '--a'],
  ['--a=1', '--a', '--b', '2'],
  ['--a', '1', '--b'],
  ['--b', '--a', '1'],
  ['--a', '--b'],
  ['--a', '--b', '--a', '--b'],
  ['--a', '1', '--b', '2', '--a', '3', '--b', '4'],
];
for (const c of REP) add(c, 'rep');

// --------------------------------------------------- 7. '--' in every position
const BASES = [
  ['--a', '1', '--b', '2'],
  ['--a=1', '--b=2'],
  ['--a', '1'],
  ['--b', '2'],
  [],
  ['--a', '1', '--b', '2', 'x'],
  ['-h'],
  ['--a', '-h', '--b', '2'],
];
for (const base of BASES) {
  for (let i = 0; i <= base.length; i += 1) {
    const withSep = base.slice(0, i).concat(['--'], base.slice(i));
    add(withSep, 'dashdash');
    for (let j = i; j <= withSep.length; j += 1) {
      add(withSep.slice(0, j).concat(['--'], withSep.slice(j)), 'dashdash2');
    }
  }
  // '-h' in every position
  for (let i = 0; i <= base.length; i += 1) {
    add(base.slice(0, i).concat(['-h'], base.slice(i)), 'help-pos');
    add(base.slice(0, i).concat(['--help'], base.slice(i)), 'help-pos');
    add(base.slice(0, i).concat(['--h'], base.slice(i)), 'help-pos');
    add(base.slice(0, i).concat(['-hx'], base.slice(i)), 'help-pos');
    add(base.slice(0, i).concat(['--help=x'], base.slice(i)), 'help-pos');
    add(base.slice(0, i).concat(['-h=x'], base.slice(i)), 'help-pos');
  }
  // extra positionals in every position
  for (let i = 0; i <= base.length; i += 1) {
    for (const p of ['x', '', ' ', '1', '- x', '-x', 'a b', '=', '--x']) {
      add(base.slice(0, i).concat([p], base.slice(i)), 'extra');
    }
  }
}

// -------------------------------------------------- 8. spaces / empty strings
const SPACEY = ['', ' ', '  ', ' x', 'x ', ' x ', '\tx', 'x\n', '- x', ' -x',
  '-x ', ' --a', '--a ', 'a b', ' - ', ' ', '　', ' ٥', '\n', '\t'];
for (const v of SPACEY) {
  add(['--a', v, '--b', '2'], 'space');
  add(['--a', '1', '--b', v], 'space');
  add(['--a=' + v, '--b=' + v], 'space');
  add([v], 'space');
  add([v, v], 'space');
  add(['--a', v, '--b', v], 'space');
  add([v, '--a', '1', '--b', '2'], 'space');
}

// ------------------------------------------------- 9. missing required combos
const MISSING = [
  [], ['--a', '1'], ['--b', '2'], ['--a=1'], ['--b=2'], ['-h'], ['--'],
  ['--', '--a', '1', '--b', '2'], ['x'], ['--a', '1', 'x'], ['x', '--b', '2'],
  ['--a', '1', '--b', '2'], ['--a', ''], ['--b', ''], ['--a', '', '--b', ''],
  ['--h', 'x'], ['-x', '--a', '1'], ['--a', '1', '-x'], ['-x'], ['-x', '-y'],
];
for (const c of MISSING) add(c, 'missing');

// ----------------------------------------------------- 10. valid value matrix
const OKVALS = ['1', '2', 'a', 'A', 'z', '', ' ', '0', 'null', 'true', '[]',
  '{}', '"', "'", '\\', 'é', '٥', '😀', '', '',
  'b', '~', 'ÿ', 'x'.repeat(40)];
for (const v of OKVALS) {
  for (const w of ['1', 'zzz', '', v]) {
    add(['--a', v, '--b', w], 'vals');
    add(['--a=' + v, '--b=' + w], 'vals');
  }
}

// ------------------------------------------------------------ 11. COLUMNS env
const COLS = ['', '20', '40', '80', '15', '10', '1', '0', '-5', '40abc', '0x10',
  ' 40 ', '40.5', '+40', '40_000', '４０', 'abc', '1e3', '  ', '999999',
  '25', '30', '  30  ', '030', '3_0'];
for (const c of COLS) {
  cases.push({ argv: ['-h'], env: { COLUMNS: c }, label: `columns COLUMNS=${JSON.stringify(c)} -h` });
  cases.push({ argv: ['--a', '1'], env: { COLUMNS: c }, label: `columns COLUMNS=${JSON.stringify(c)} missing` });
}

// -------------------------------------------------------------------- run
const mine = cases.filter((_, i) => i % SHARDS === SHARD);
process.stdout.write(`shard ${SHARD}/${SHARDS}: ${mine.length} of ${cases.length} cases\n`);
const failed = runSuite(`argparse-state-machine#${SHARD}`, mine);
process.exitCode = failed > 0 ? 1 : 0;

