/**
 * argparse-state-machine2.mjs — wave 2 of the argparse campaign.
 *
 * Usage: node argparse-state-machine2.mjs [shardIndex shardCount]
 */
import { runSuite } from '/tmp/dh/harness.mjs';

const argvIn = process.argv.slice(2);
const SHARD = argvIn.length >= 2 ? parseInt(argvIn[0], 10) : 0;
const SHARDS = argvIn.length >= 2 ? parseInt(argvIn[1], 10) : 1;

const cases = [];
const seen = new Set();
function add(argv, tag, env) {
  const key = JSON.stringify([argv.map(String), env || null]);
  if (seen.has(key)) return;
  seen.add(key);
  const entry = { argv, label: `${tag}: ` + argv.map((a) => JSON.stringify(String(a))).join(' ') };
  if (env) {
    entry.env = env;
    entry.label += ` [env ${JSON.stringify(env)}]`;
  }
  cases.push(entry);
}
let _s = 0x51f3a7d;
const rnd = () => ((_s = (_s * 1103515245 + 12345) & 0x7fffffff) / 0x80000000);
const pick = (a) => a[Math.floor(rnd() * a.length) % a.length];

// ---------------- 2A. second exhaustive alphabet (options-heavy) -------------
const A2 = [
  '--h', '--he', '--hel', '--help', '--ab', '--aa', '--A', '-a', '---a', '-hx',
  '-h=x', '--help=x', '--a=', '--a==1', '--b=', '-5', '-٥', '- 5', '+5', '=1',
];
for (const a of A2) add([a], 'w2len1');
for (const a of A2) for (const b of A2) add([a, b], 'w2len2');
for (const a of A2) for (const b of A2) for (const c of A2) add([a, b, c], 'w2len3');

// ---------------- 2B. valid parses interleaved with every token --------------
const TOKENS = [
  '--a', '--b', '-h', '--help', '--h', '--he', '--', '---', '----', '--=',
  '--=x', '-=', '-=x', '-x', '-a', '-b', '-hh', '-hhx', '-h-x', '-h=', '-h ',
  '--a=1', '--a=', '--a==', '--a=-x', '--a=--', '--b=2', '--A', '--B', '-H',
  '', ' ', 'x', '1', '-5', '-.5', '-0.0', '-0009', '-1.', '-1.5e3', '-5x',
  '- 5', '-5 ', '+5', '--5', '-', '=', '=x', 'a=b', '--a b', '-x y', '--ab',
  '--aa', '--ba', '--helpp', '--hell', '--a-', '-٥', '-٥٦', '-५', '-１', '-𝟝',
];
const BASE = ['--a', '1', '--b', '2'];
for (const t of TOKENS) {
  for (let i = 0; i <= BASE.length; i += 1) {
    add(BASE.slice(0, i).concat([t], BASE.slice(i)), 'w2insert');
  }
  add([t], 'w2solo');
  add([t, t], 'w2solo2');
  add(['--a', t], 'w2aval');
  add(['--b', t], 'w2bval');
  add(['--a', t, '--b', t], 'w2both');
  add(['--a=' + t, '--b=' + t], 'w2eqboth');
  add(['--', t], 'w2after');
  add([t, '--'], 'w2before');
  add(['--a', '1', '--b', '2', '--', t], 'w2sepafter');
  add(['--a', '1', '--', t, '--b', '2'], 'w2sepmid');
}

// ---------------- 2C. Unicode Nd digits, every script family ----------------
const DIGITS = [
  '0', '٥', '۵', '٠', '५', '০', '௫', '๕', '໕', '༥', '၅', '០', '᠕', '᥅', '０',
  '𝟎', '𝟝', '𝟵', '𐒥', '꘥', '𑁫', '௦', '༠', '𝟘', '½', '⁵', '₅', '五', 'Ⅴ', '➄',
];
for (const d of DIGITS) {
  for (const v of ['-' + d, '-' + d + d, '-' + d + '.' + d, '-.' + d, '-' + d + '.', '-' + d + 'x', '-5' + d, '-' + d + '5']) {
    add(['--a', v, '--b', '2'], 'w2digit');
    add(['--b', '2', '--a', v], 'w2digit');
    add([v], 'w2digit');
    add(['--a', '1', '--b', '2', v], 'w2digit');
    add(['--a=' + v, '--b', v], 'w2digit');
  }
}

// ---------------- 2D. short-option chaining off '-h' ------------------------
const TAILS = ['h', 'x', 'hh', 'hx', 'xh', '5', '-', '-x', '=', '=x', 'h=x',
  'hh=x', ' ', ' x', 'x ', '٥', '😀', 'help', 'e', 'l', 'p', 'H', 'a', 'b',
  'h-', 'h-x', 'hhh', 'hhhh', 'h=', 'x=y', '--', 'h--'];
for (const t of TAILS) {
  add(['-h' + t], 'w2chain');
  add(['-h' + t, '--a', '1', '--b', '2'], 'w2chain');
  add(['--a', '1', '--b', '2', '-h' + t], 'w2chain');
  add(['-' + t], 'w2chain-');
  add(['--' + t], 'w2chain--');
  add(['--a', '1', '--b', '2', '--' + t], 'w2chain--');
}

// ---------------- 2E. randomised long vectors -------------------------------
for (let n = 5; n <= 9; n += 1) {
  for (let i = 0; i < 700; i += 1) {
    const argv = [];
    for (let k = 0; k < n; k += 1) argv.push(pick(TOKENS));
    add(argv, `w2len${n}`);
  }
}

// ---------------- 2F. COLUMNS sweep across every output path ---------------
const PATHS = [
  { argv: ['-h'], tag: 'help' },
  { argv: ['--a', '1'], tag: 'missing' },
  { argv: ['--a', '1', '--b', '2', 'x'], tag: 'unrecognized' },
  { argv: ['--a'], tag: 'expected-one' },
  { argv: ['--=1'], tag: 'ambiguous' },
];
for (let c = 1; c <= 90; c += 1) {
  for (const p of PATHS) add(p.argv, `w2cols-${p.tag}`, { COLUMNS: String(c) });
}
for (const c of ['', ' ', 'abc', '40abc', '30abc', '0x10', '1e3', '４０', '40_000',
  '3_0', '40.5', '+40', '-40', ' 40 ', '4 0', '٤٠', '0b1010', '00040', '9'.repeat(20)]) {
  for (const p of PATHS) add(p.argv, `w2colstr-${p.tag}`, { COLUMNS: c });
}
// LINES must not matter (Python only consults it for rows)
for (const l of ['1', '0', 'abc', '']) add(['-h'], 'w2lines', { LINES: l });

// -------------------------------------------------------------------- run
const mine = cases.filter((_, i) => i % SHARDS === SHARD);
process.stdout.write(`shard ${SHARD}/${SHARDS}: ${mine.length} of ${cases.length} cases\n`);
const failed = runSuite(`w2#${SHARD}`, mine);
process.exitCode = failed > 0 ? 1 : 0;

