cd /tmp/dh && cat > /tmp/dh/probe6.mjs <<'EOF'
import { runCase } from '/tmp/dh/harness.mjs';
const tails = ['x', '\t', 'a\nb', "it's", '\x01', '\x7f', 'é', '​', 'a\\b', "'", '"', ' ', '😀', 'a b'];
const forms = (t) => [['--help=' + t], ['-h=' + t], ['--h=' + t], ['--he=' + t]];
for (const t of tails) {
  for (const argv of forms(t)) {
    const { py, js } = runCase(argv);
    const same = py.code === js.code && py.out.equals(js.out) && py.err.equals(js.err);
    if (!same) {
      console.log('DIFF', JSON.stringify(argv));
      console.log('   py', py.code, JSON.stringify(py.err.toString('latin1').split('\n')[1]));
      console.log('   js', js.code, JSON.stringify(js.err.toString('latin1').split('\n')[1]));
    }
  }
}
// invalid UTF-8 tails
const raw = (b) => Buffer.from(b, 'latin1');
for (const t of [raw('--help=\x80'), raw('-h=\xff'), raw('--help=a\x80b')]) {
  const { py, js } = runCase([t]);
  const same = py.code === js.code && py.out.equals(js.out) && py.err.equals(js.err);
  if (!same) {
    console.log('DIFF', JSON.stringify(t.toString('latin1')));
    console.log('   py', py.code, JSON.stringify(py.err.toString('latin1')));
    console.log('   js', js.code, JSON.stringify(js.err.toString('latin1')));
  }
}
console.log('probe6 done');
EOF
node /tmp/dh/probe6.mjs
